-- Extend the existing Law 1 quiz while preserving its question and passing score.
begin;
with additions as (
  select     '[{"id":"identify-the-risk","questionEn":"A project lead introduces your prototype to sponsors. Which risk does this lesson most directly address?","questionBn":"একজন প্রকল্পনেতা পৃষ্ঠপোষকদের কাছে আপনার প্রোটোটাইপ তুলে ধরছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["An absence or departure can interrupt an essential service when knowledge is concentrated.","Personal relationships can bias judgments about who will perform well.","Visible contributions may be mistaken for a challenge to the lead''s status.","Announcing tentative terms can reduce room to negotiate or create premature expectations."],"optionsBn":["জ্ঞান একজনের হাতে কেন্দ্রীভূত থাকলে তাঁর অনুপস্থিতি বা প্রস্থানে জরুরি সেবা বন্ধ হতে পারে।","ব্যক্তিগত সম্পর্ক কে ভালো কাজ করবেন সেই বিচারে পক্ষপাত আনতে পারে।","প্রকাশ্য অবদানকে নেতার মর্যাদার প্রতি চ্যালেঞ্জ বলে ভুল বোঝা হতে পারে।","অস্থায়ী শর্ত ঘোষণা করলে আলোচনার সুযোগ কমে বা অকালে প্রত্যাশা তৈরি হয়।"],"correctOption":2,"explanationEn":"Visible contributions may be mistaken for a challenge to the lead''s status.","explanationBn":"প্রকাশ্য অবদানকে নেতার মর্যাদার প্রতি চ্যালেঞ্জ বলে ভুল বোঝা হতে পারে।"},{"id":"apply-the-boundary","questionEn":"A project lead introduces your prototype to sponsors. Which safeguard best prevents misusing this principle here?","questionBn":"একজন প্রকল্পনেতা পৃষ্ঠপোষকদের কাছে আপনার প্রোটোটাইপ তুলে ধরছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Distinguish legitimate confidentiality from omissions that affect informed consent. Name when and to whom more can be disclosed.","If quality or safety is at risk, raise the facts through the responsible channel promptly. Giving credit should never obscure who did the work.","Brevity works when the listener can act on what you said. Include dependencies or uncertainty if leaving them out would cause a bad decision.","A quick correction builds trust only when it is as visible as the original claim. Record the process that prevented the verification step."],"optionsBn":["বৈধ গোপনীয়তা ও অবহিত সম্মতিতে প্রভাব ফেলা তথ্য গোপনের পার্থক্য বুঝুন। কখন ও কাকে বিস্তারিত বলা যাবে তা জানান।","মান বা নিরাপত্তা ঝুঁকিতে থাকলে দায়িত্বপ্রাপ্ত পথে দ্রুত তথ্য জানান। কৃতিত্ব ভাগ করতে গিয়ে কে কাজ করেছেন তা আড়াল করা উচিত নয়।","শ্রোতা আপনার কথা থেকে কাজ করতে পারলেই সংক্ষিপ্ততা কার্যকর। বাদ দিলে ভুল সিদ্ধান্ত হতে পারে এমন নির্ভরতা বা অনিশ্চয়তা জানান।","দ্রুত সংশোধনী তখনই আস্থা গড়ে যখন তা মূল দাবির মতোই দৃশ্যমান হয়। কোন প্রক্রিয়ায় যাচাই বাদ পড়েছিল তা নথিভুক্ত করুন।"],"correctOption":1,"explanationEn":"If quality or safety is at risk, raise the facts through the responsible channel promptly. Giving credit should never obscure who did the work.","explanationBn":"মান বা নিরাপত্তা ঝুঁকিতে থাকলে দায়িত্বপ্রাপ্ত পথে দ্রুত তথ্য জানান। কৃতিত্ব ভাগ করতে গিয়ে কে কাজ করেছেন তা আড়াল করা উচিত নয়।"}]'::jsonb as questions
)
update public.content_laws l
set assessment = jsonb_set(l.assessment, '{questions}', (l.assessment->'questions') || a.questions)
from additions a
where l.slug = 'never-outshine-the-master'
  and l.assessment->>'isPublished' = 'true'
  and jsonb_array_length(l.assessment->'questions') = 1
  and not exists (
    select 1 from jsonb_array_elements(l.assessment->'questions') existing
    join jsonb_array_elements(a.questions) candidate on existing->>'id' = candidate->>'id'
  );
commit;
